#define PI 3.14159265359

// --- Customizable Parameters ---

float tunnelLength = 10.0;     // Length of the tunnel

float tunnelRadius = 1.0;     // Radius of the tunnel

float segmentWidth = 0.2;     // Width of each segment/column

float rotationSpeed = 0.2;    // Speed of rotation

float patternScale = 8.0;     // Scale of the pattern on the columns

float colorSpeed = 0.5;       // Speed of color cycling

float zoom = 1.0;

// --- End Customizable Parameters ---

// Function to create a repeating pattern

float pattern(vec2 uv) {

    return 0.5 + 0.5 * sin(uv.x * patternScale + sin(uv.y*patternScale*0.5+iTime*0.5));

}

void mainImage( out vec4 fragColor, in vec2 fragCoord )

{

    vec2 uv = fragCoord / iResolution.xy;

    uv -= 0.5;

    uv *= zoom;

    // Convert to polar coordinates

    float angle = atan(uv.y, uv.x);

    float radius = length(uv);

    // Create tunnel effect

    float z = iTime * rotationSpeed; // Z position in the tunnel

    float segment = mod(angle * tunnelRadius, segmentWidth); // Segment along the circumference

    float tunnelPos = mod(z + radius * tunnelLength, tunnelLength);

    // Calculate column position

    float column = floor(angle * tunnelRadius / segmentWidth);

    // Get pattern UVs

    vec2 patternUV = vec2(mod(column,4.0), tunnelPos);

    // Sample pattern

    float pat = pattern(patternUV);

    // Color cycling

    vec3 col;

    float colorOffset = mod(iTime * colorSpeed + column*0.2, 1.0);

    col.r = sin(colorOffset * 6.283 + 0.0);

    col.g = sin(colorOffset * 6.283 + 2.0);

    col.b = sin(colorOffset * 6.283 + 4.0);

    // Apply pattern to color

    col *= pat;

    //Darken the spaces between the columns

    if(segment < 0.02 || segment > segmentWidth-0.02){

        col *= 0.1;

    }

    fragColor = vec4(col, 1.0);

}
